import React, { useState } from 'react';

function App() {
  const [fullName, changefun] = useState("");

  const press = (event)=>{
    changefun(event.target.value);
  };
  const submit = (event) => {
      event.preventDefault();
  };

  return (
    <>
      <div className='main'>
        <form onSubmit={submit}>
          <div className='textarea'>
              Hello {fullName}
          </div><br/>
          <input type='text' 
          placeholder='Enter Your firstName' 
          onChange={press} 
          // value='fname'
          className='input'/>
          <br/><br/>
          <input type='text' 
          placeholder='Enter Your LastName' 
          onChange={press} 
          // value='lname'
          className='input'/>
          <br/><br/>
          <button  type='submit' className='btn'>Submit</button>
        </form>  
      </div>
    </>
  );
}

export default App;
